## The third paragraph
The following code is the core. The author simplifies the core method code through the separation of responsibilities.
```typescript
// Core method
function urlcatImpl(
  pathTemplate: string,
  params: ParamMap,
  baseUrl: string | undefined,
  config: UrlCatConfiguration
) {
    // The first step path('/users/:id/posts', { id: 1, limit: 30 }) returns "/users/1/posts" and limit: 30
  const { renderedPath, remainingParams } = path(pathTemplate, params);
    //The second step removes Null or Undefined properties
  const cleanParams = removeNullOrUndef(remainingParams);
    //The third step is {limit: 30} to limit=30
  const renderedQuery = query(cleanParams, config);
    // Step 4: Splice and return /users/1/posts?limit=30
  const pathAndQuery = join(renderedPath, '?', renderedQuery);

    // Step 5: When baseUrl exists, perform complete url splicing
  return baseUrl ? joinFullUrl(renderedPath, baseUrl, pathAndQuery) : pathAndQuery;
}
```
